create table public.teams (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_at timestamptz not null default now()
);
create table public.team_members (
  team_id uuid not null references public.teams (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (team_id, user_id)
);
create table public.team_documents (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references public.teams (id) on delete cascade,
  title text not null,
  body text,
  created_at timestamptz not null default now()
);
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.team_documents enable row level security;
create policy "members read their teams"
  on public.teams for select
  using (exists (select 1 from public.team_members where team_id = teams.id and user_id = auth.uid()));
create policy "members read team membership"
  on public.team_members for select
  using (exists (select 1 from public.team_members m where m.team_id = team_members.team_id and m.user_id = auth.uid()));
create policy "users join teams"
  on public.team_members for insert
  with check (auth.uid() = user_id);
create policy "members read team docs"
  on public.team_documents for select
  using (exists (select 1 from public.team_members where team_members.team_id = team_documents.team_id and team_members.user_id = auth.uid()));
